files.scripts/checkPool.js:
const fs = require('fs');
const path = process.argv[2];
const content = fs.readFileSync(path, 'utf8');
const match = content.match(/pool_size:\s*(\d+)/);
if (!match) {
  console.error('FAIL: no pool_size found in ' + path);
  process.exit(1);
}
const value = parseInt(match[1], 10);
if (value < 10 || value > 50) {
  console.error(`FAIL: pool_size ${value} out of bounds [10,50] in ${path}`);
  process.exit(1);
}
console.log(`OK: ${path} pool_size=${value}`);

